*{box-sizing:border-box}
.icon-btn:disabled{opacity:.42;cursor:not-allowed}
.icon-btn:not(:disabled):hover{background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.35)}
 :root{font-family:'DM Sans',sans-serif;color:#f5f4ed;background:#172422;font-synthesis:none;--cream:#f3f1e8;--ink:#1e2926;--muted:#a9b5ad;--green:#bfd58e;--deep:#152220}
html,body,#game{width:100%;height:100%;margin:0;overflow:hidden}
body{overscroll-behavior:none}
#game{position:relative;background:#b8cdbb}
#world{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.topbar{position:absolute;top:0;left:0;right:0;height:82px;padding:0 38px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(13,25,24,.84),rgba(13,25,24,.54));backdrop-filter:blur(16px);z-index:3}
.brand{display:flex;align-items:center;gap:12px;letter-spacing:1.6px}
.brand-mark{width:35px;height:35px;border-radius:11px;background:#d6e5ad;color:#304538;display:grid;place-items:center;font:800 21px Manrope;transform:rotate(-5deg)}
.brand strong{font:800 13px Manrope;display:block}
.brand small,.location small{display:block;color:#aab8ad;font-size:9px;letter-spacing:1.2px;margin-top:3px}
.location{display:flex;align-items:center;gap:10px;padding:9px 16px;border:1px solid rgba(255,255,255,.14);border-radius:12px;background:rgba(255,255,255,.07);font-size:12px}
.location small{font-size:10px;letter-spacing:.2px}
.live-dot{width:7px;height:7px;background:#d2ed9d;border-radius:50%;box-shadow:0 0 12px #c7e394}
.top-actions{display:flex;gap:10px;align-items:center}
.icon-btn,.avatar{width:35px;height:35px;border:1px solid rgba(255,255,255,.16);border-radius:11px;background:rgba(255,255,255,.08);color:#fff;font-size:15px;cursor:pointer}
.avatar{border:0;background:#e8c5a2;color:#4b4838;font-weight:700}
.mission-card{position:absolute;left:5.2%;top:19%;z-index:2;max-width:290px;pointer-events:none;text-shadow:0 2px 22px rgba(8,21,17,.24)}
.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.8px;color:#d9e8bd}
