*{box-sizing:border-box}
.icon-btn:disabled{opacity:.42;cursor:not-allowed}
.icon-btn:not(:disabled):hover{background:rgba(255,255,255,.18);border-color:rgba(255,255,255,.35)}
 :root{font-family:'DM Sans',sans-serif;color:#f5f4ed;background:#172422;font-synthesis:none;--cream:#f3f1e8;--ink:#1e2926;--muted:#a9b5ad;--green:#bfd58e;--deep:#152220}
html,body,#game{width:100%;height:100%;margin:0;overflow:hidden}
body{overscroll-behavior:none}
#game{position:relative;background:#b8cdbb}
#world{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none}
.topbar{position:absolute;top:0;left:0;right:0;height:82px;padding:0 38px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(13,25,24,.84),rgba(13,25,24,.54));backdrop-filter:blur(16px);z-index:3}
.brand{display:flex;align-items:center;gap:12px;letter-spacing:1.6px}
.brand-mark{width:35px;height:35px;border-radius:11px;background:#d6e5ad;color:#304538;display:grid;place-items:center;font:800 21px Manrope;transform:rotate(-5deg)}
.brand strong{font:800 13px Manrope;display:block}
.brand small,.location small{display:block;color:#aab8ad;font-size:9px;letter-spacing:1.2px;margin-top:3px}
.location{display:flex;align-items:center;gap:10px;padding:9px 16px;border:1px solid rgba(255,255,255,.14);border-radius:12px;background:rgba(255,255,255,.07);font-size:12px}
.location small{font-size:10px;letter-spacing:.2px}
.live-dot{width:7px;height:7px;background:#d2ed9d;border-radius:50%;box-shadow:0 0 12px #c7e394}
.top-actions{display:flex;gap:10px;align-items:center}
.icon-btn,.avatar{width:35px;height:35px;border:1px solid rgba(255,255,255,.16);border-radius:11px;background:rgba(255,255,255,.08);color:#fff;font-size:15px;cursor:pointer}
.avatar{border:0;background:#e8c5a2;color:#4b4838;font-weight:700}
.mission-card{position:absolute;left:5.2%;top:19%;z-index:2;max-width:290px;pointer-events:none;text-shadow:0 2px 22px rgba(8,21,17,.24)}
.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.8px;color:#d9e8bd}
.mission-card h1{font:700 clamp(38px,4vw,54px)/1.01 Manrope;margin:12px 0 12px;letter-spacing:-2.2px}
.mission-card h1 em,.help-panel h2 em{font-family:Georgia,serif;font-weight:400;color:#d9e7ad}
.mission-card p{font-size:12px;line-height:1.6;color:#edf0e7;max-width:235px;margin:0}
.world-meta{display:flex;gap:9px;margin-top:20px}
.world-meta span{font-size:8px;letter-spacing:1px;padding:8px 10px;border:1px solid rgba(255,255,255,.24);border-radius:20px;background:rgba(18,34,27,.2);backdrop-filter:blur(5px)}
.world-status{position:absolute;right:36px;top:102px;z-index:2;display:flex;align-items:center;gap:10px;padding:10px 13px;border:1px solid rgba(255,255,255,.5);border-radius:13px;background:rgba(240,239,222,.84);color:#34453c;box-shadow:0 8px 25px #13241c20;backdrop-filter:blur(12px)}
.sun-icon{font-size:21px;color:#c2914f}
.world-status b{font-size:11px}
.world-status small{display:block;font-size:9px;color:#819088;margin-top:2px}
.world-status i{height:27px;border-left:1px solid #d2d7ca;margin:0 3px}
.status-coords{text-align:right}
.crosshair{pointer-events:none;position:absolute;left:50%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);opacity:.54}
.crosshair span{position:absolute;background:#fff;box-shadow:0 1px 3px #16251e}
.crosshair span:first-child{width:1px;height:15px;left:8px}
.crosshair span:last-child{height:1px;width:15px;top:7px}
.controls-hint{position:absolute;bottom:25px;left:50%;transform:translateX(-50%);z-index:2;padding:9px 14px;border:1px solid rgba(255,255,255,.3);border-radius:9px;background:rgba(25,41,34,.5);backdrop-filter:blur(8px);font-size:8px;letter-spacing:1.2px;color:#f2f0e5;white-space:nowrap}
.controls-hint span{font-weight:700;padding:4px 5px;border:1px solid #ffffff50;border-radius:4px;margin-right:4px}
.controls-hint i{display:inline-block;height:10px;border-left:1px solid #ffffff55;margin:0 10px -2px}
.inventory-toggle{position:absolute;z-index:4;bottom:24px;left:29px;height:54px;padding:0 14px;display:flex;align-items:center;gap:10px;border:1px solid #ffffff40;border-radius:13px;background:rgba(20,37,30,.88);color:#f7f3e8;box-shadow:0 8px 30px #17251c35;cursor:pointer}
.inventory-toggle>span{font-size:20px;color:#d7e5b5}
.inventory-toggle b{font-size:10px;letter-spacing:1.1px}
.inventory-toggle small{font-size:8px;color:#9daaa0;border-left:1px solid #ffffff30;padding-left:9px}
.inventory-toggle kbd{font:10px 'DM Sans';margin-left:7px;padding:4px 6px;border:1px solid #ffffff35;border-radius:5px;color:#bac4b7}
.inventory{position:absolute;z-index:6;left:24px;top:50%;transform:translate(-115%,-50%);width:min(410px,calc(100vw - 32px));height:min(690px,calc(100vh - 112px));padding:20px;background:rgba(246,246,236,.97);color:#24332d;border:1px solid #fff;border-radius:19px;box-shadow:0 20px 70px #11241b50;display:flex;flex-direction:column;transition:transform .35s cubic-bezier(.22,.8,.25,1);backdrop-filter:blur(22px)}
.inventory.open{transform:translate(0,-50%)}
.inventory-head{display:flex;align-items:flex-start;justify-content:space-between}
.inventory .eyebrow{color:#879778;font-size:8px}
.inventory h2{font:700 23px Manrope;margin:3px 0 0;letter-spacing:-.7px}
.inventory h2 span{font:600 10px 'DM Sans';color:#97a195;margin-left:4px}
.close-btn{border:0;background:transparent;color:#7a877d;font-size:25px;line-height:1;cursor:pointer}
.inventory-tools{display:flex;gap:8px;margin:16px 0 12px}
.search{height:39px;display:flex;align-items:center;gap:8px;flex:1;background:#edf0e8;border:1px solid #e1e6dc;border-radius:9px;padding:0 10px;color:#809083}
.search span{font-size:21px;line-height:1}
.search input{width:100%;border:0;outline:0;background:transparent;color:#34433a;font:11px 'DM Sans'}
.filter-btn{width:39px;border:1px solid #e1e6dc;background:#edf0e8;border-radius:9px;color:#778a6d;font-size:19px;cursor:pointer}
.filter-btn.active{background:#dce7c9;color:#3e6644}
.categories{display:flex;gap:6px;overflow-x:auto;padding-bottom:12px;scrollbar-width:none}
.categories::-webkit-scrollbar,.items-grid::-webkit-scrollbar{display:none}
.category{white-space:nowrap;border:1px solid #dfe4da;background:#f8f8f2;color:#738075;border-radius:16px;padding:7px 10px;font:600 9px 'DM Sans';cursor:pointer}
.category.active{background:#30483d;color:#eef3df;border-color:#30483d}
.selection-note{display:flex;align-items:center;gap:9px;background:#e8eedc;border:1px solid #dae5cc;border-radius:10px;padding:9px 10px;margin-bottom:12px;min-height:53px}
.selection-icon{height:29px;width:29px;border-radius:8px;background:#d2dfbd;display:grid;place-items:center;color:#5d7651}
.selection-note b{font-size:10px;display:block}
.selection-note small{font-size:9px;color:#849083;display:block;margin-top:3px}
.equip-btn{margin-left:auto;border:0;border-radius:7px;background:#3a5545;color:#f4f4e9;padding:8px 10px;font:700 8px 'DM Sans';letter-spacing:.8px;cursor:pointer}
.equip-btn:disabled{opacity:.45}
.items-grid{overflow:auto;display:grid;grid-template-columns:repeat(4,1fr);gap:8px;align-content:start;padding:1px 2px 12px;scrollbar-width:thin;scrollbar-color:#d4ddce transparent}
.item-card{min-height:79px;border:1px solid #e5e8df;border-radius:10px;background:#fbfbf7;padding:8px 7px 7px;display:flex;flex-direction:column;align-items:center;justify-content:space-between;cursor:pointer;transition:.15s;position:relative}
.item-card:hover{border-color:#b3c39c;transform:translateY(-1px)}
.item-card.selected{border:1.5px solid #657f5a;background:#f0f4e7;box-shadow:0 0 0 2px #cbd9ba70}
.item-swatch{height:34px;width:36px;border-radius:7px;position:relative;display:grid;place-items:center;overflow:hidden;box-shadow:inset 0 0 0 1px #0000000c}
.item-swatch::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,#ffffff48,transparent 58%,#00000012)}
.item-swatch span{z-index:1;font-size:17px;color:#ffffffda;text-shadow:0 1px 4px #0006}
.item-card b{font-size:8.5px;font-weight:600;color:#536157;text-align:center;line-height:1.15}
.item-card em{position:absolute;top:4px;right:5px;font-style:normal;color:#a6b27e;font-size:10px}
.inventory-foot{display:flex;justify-content:space-between;border-top:1px solid #e3e7dd;padding-top:10px;margin-top:auto;font-size:8px;letter-spacing:.65px;color:#89958a}
.inventory-foot span:first-child{color:#73846c}
.selected-chip{position:absolute;right:28px;bottom:24px;z-index:3;display:flex;align-items:center;gap:10px;padding:9px 11px;background:rgba(246,246,236,.94);color:#2e4036;border:1px solid white;border-radius:12px;box-shadow:0 8px 25px #11241b30;min-width:170px}
.chip-swatch{height:28px;width:28px;border-radius:7px;background:#96693f;box-shadow:inset 0 0 0 1px #0002}
.selected-chip small{display:block;color:#819082;font-size:7px;letter-spacing:1px;margin-bottom:2px}
.selected-chip b{font-size:10px}
.selected-chip button{margin-left:auto;border:0;background:#e6ecd9;color:#58744c;width:27px;height:27px;border-radius:7px;font-size:17px;cursor:pointer}
.touch-controls{display:none}
.toast{position:absolute;z-index:9;left:50%;top:90px;transform:translate(-50%,-12px);padding:10px 16px;border-radius:10px;background:#263a2f;color:#f6f5ea;font-size:11px;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 8px 22px #12271d50}
.toast.show{opacity:1;transform:translate(-50%,0)}
.help-modal{position:absolute;inset:0;z-index:10;background:#10201999;backdrop-filter:blur(6px);display:none;align-items:center;justify-content:center;padding:20px}
.help-modal.open{display:flex}
.help-panel{position:relative;background:#f5f4e9;color:#2d3b33;width:min(420px,100%);border-radius:20px;padding:30px;box-shadow:0 22px 80px #10201970}
.help-panel .close-btn{position:absolute;right:18px;top:16px}
.help-panel .eyebrow{color:#849477}
.help-panel h2{font:700 32px/1.05 Manrope;letter-spacing:-1.3px;margin:10px 0}
.help-panel h2 em{color:#779266}
.help-panel p{font-size:12px;line-height:1.7;color:#69786c}
.help-tip{display:flex;gap:11px;background:#e7eddd;padding:12px;border-radius:10px;margin:18px 0}
.help-tip>span{color:#829d64}
.help-tip b,.help-tip small{display:block}
.help-tip b{font-size:11px}
.help-tip small{font-size:10px;color:#79877a;line-height:1.5;margin-top:4px}
.primary-btn{width:100%;height:42px;border:0;border-radius:9px;background:#3a5545;color:#f5f5e9;font:700 10px 'DM Sans';letter-spacing:1px;cursor:pointer}
.loading-cover{position:absolute;inset:0;z-index:20;background:#193126;display:flex;flex-direction:column;align-items:center;justify-content:center;transition:opacity .7s}
.loading-cover.done{opacity:0;pointer-events:none}
.loader-mark{width:48px;height:48px;border-radius:16px;background:#d7e5b5;color:#334b39;display:grid;place-items:center;font:800 27px Manrope;animation:breathe 1.4s infinite alternate}
.loading-title{font:800 11px Manrope;letter-spacing:3px;margin-top:16px}
.loading-sub{font-size:10px;color:#a8b8a7;margin-top:7px}
.loading-bar{width:120px;height:2px;background:#ffffff25;margin-top:20px;border-radius:5px;overflow:hidden}
.loading-bar i{display:block;width:45%;height:100%;background:#c9dc9e;animation:load 1.1s infinite ease-in-out}
@keyframes load{from{transform:translateX(-120%)}
to{transform:translateX(240%)}
}
@keyframes breathe{to{transform:scale(1.08);box-shadow:0 0 30px #cfe4a955}
}
@media(max-width:700px){.topbar{height:64px;padding:0 14px}
.brand strong{font-size:11px}
.brand small{font-size:7px}
.brand-mark{width:31px;height:31px}
.location{padding:7px 9px;gap:7px}
.location b{font-size:10px}
.location small{font-size:8px}
.top-actions{gap:5px}
.icon-btn,.avatar{width:31px;height:31px}
.mission-card{left:18px;top:15%;max-width:210px}
.mission-card h1{font-size:38px}
.mission-card p{font-size:10px;max-width:180px}
.world-meta{margin-top:12px}
.world-meta span{font-size:7px;padding:6px 8px}
.world-status{right:12px;top:75px;padding:8px 9px}
.world-status .status-coords{display:none}
.world-status i{display:none}
.world-status b{font-size:10px}
.inventory{left:8px;width:calc(100vw - 16px);height:min(67vh,590px);top:auto;bottom:8px;transform:translateY(120%);padding:14px;border-radius:17px}
.inventory.open{transform:translateY(0)}
.inventory h2{font-size:20px}
.items-grid{grid-template-columns:repeat(4,1fr);gap:6px}
.item-card{min-height:70px}
.item-swatch{height:30px;width:32px}
.inventory-toggle{left:12px;bottom:13px;height:48px;padding:0 11px}
.inventory-toggle small,.inventory-toggle kbd{display:none}
.selected-chip{right:12px;bottom:13px;min-width:145px;padding:7px}
.controls-hint{display:none}
.touch-controls{display:block}
.stick-zone{position:absolute;bottom:82px;left:20px;width:112px;height:112px;border-radius:50%;border:1px solid #ffffff70;background:#172c2266;backdrop-filter:blur(4px);touch-action:none}
.stick-zone:before,.stick-zone:after{content:'';position:absolute;background:#ffffff25}
.stick-zone:before{left:50%;top:12px;bottom:12px;width:1px}
.stick-zone:after{top:50%;left:12px;right:12px;height:1px}
.stick-knob{position:absolute;left:50%;top:50%;width:43px;height:43px;transform:translate(-50%,-50%);border-radius:50%;background:#e2ebcc;border:2px solid #ffffff90;box-shadow:0 3px 12px #10251c70;z-index:2}
.touch-actions{position:absolute;right:22px;bottom:91px;display:flex;flex-direction:column;gap:12px}
.round-action,.place-action{border:1px solid #ffffff85;border-radius:50%;background:#263c30c9;color:#f5f2e7;width:48px;height:48px;font-size:19px;backdrop-filter:blur(5px)}
.place-action{width:59px;height:59px;background:#d9e8b6;color:#324b39;font-size:26px}
.touch-actions small{display:none}
.crosshair{top:48%}
.toast{top:72px}
.help-panel{padding:25px}
.inventory.open~.inventory-toggle,.inventory.open~.selected-chip{display:none}
}
@media(min-width:701px) and (max-height:650px){.inventory{height:calc(100vh - 90px);padding:14px}
.mission-card{top:17%}
.mission-card h1{font-size:42px}
}

