import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', error => errors.push(error.message))
  page.on('console', message => { if (message.type() === 'error') errors.push(message.text()) })
  const response = await page.goto('http://127.0.0.1:4173', { waitUntil: 'load', timeout: 45000 })
  if (!response?.ok()) throw new Error(`Preview returned HTTP ${response?.status()}`)
  await page.evaluate(() => document.fonts.ready)
  await page.waitForTimeout(1500)
  mkdirSync('screenshots', { recursive: true })
  await page.screenshot({ path: 'screenshots/latest.jpg', type: 'jpeg', quality: 90 })
  console.log(JSON.stringify({ viewport: page.viewportSize(), errors }))
} finally { await browser.close() }

